import React, { useEffect, useState, useMemo } from "react";
import "../../../Styles/pages/SchoolSearchPanel.css";
import VirtualizedSelect from "../../shared/Ui/VirtualizedSelect";
import { supabase } from "../../../lib/supabaseClient";
import UploadSchoolListDialog from "../../UploadSchoolListDialog/UploadSchoolListDialog";
import { GLOBAL_DEBUG } from "../../../admin/debug";
import { navigate } from "gatsby";

const DEBUG = GLOBAL_DEBUG
export function SchoolSearchPanelTop() {
  return (<div></div>);
}

function SchoolSearchPanel() {
  const [schoolData, setSchoolData] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const [form, setForm] = useState({
    state: "",
    school: "",
    teacher: "",
    grade: ""
  });

  useEffect(() => {
    const fetchSchoolData = async () => {
      setIsLoading(true);
      const { data, error } = await supabase
        .from("Schools") 
        .select("*");

      if (error) {
        console.error("Error fetching schools from Supabase:", error);
      } else {
        setSchoolData(data as any);
      }

      setIsLoading(false);
    };

    fetchSchoolData();
  }, []);

  const handleChange = (e: any ) => {
    const { name, value } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSearch = () => {
    console.log("Searching with:", form);
    navigate('/v2/shop/502');
  };

  const states : any = useMemo(() => {
    const uniqueStates = [...new Set(schoolData.map((item: any) => item.State))];
    return uniqueStates.map(state => ({
      value: state,
      label: state
    }));
  }, [schoolData]);

  const schools : any = useMemo(() => {
    if (!form.state) return [];
    return schoolData
      .filter((item : any ) => item.State === form.state)
      .map(item => ({
        value: item["School Name"],
        label: item["School Name"]
      }));
  }, [schoolData, form.state]);

  // Dynamic grades from selected school
  const grades : any = useMemo(() => {
    if (!form.school) return [];

    const selectedSchool = schoolData.find(
      item => item["School Name"] === form.school
    );

    if (!selectedSchool || !selectedSchool["Grade Levels"]) return [];

    // Handle formats like "6-8" or "K-5"
    const range = (selectedSchool["Grade Levels"] as String).split("-");
    const start = range[0].trim();
    const end = range[1]?.trim();

    const gradesArray = [];

    const gradeLabel = (val : any ) =>
      val === "K" ? "Kindergarten" : `Grade ${val}`;

    if (start === "K") gradesArray.push({ value: "K", label: gradeLabel("K") });

    const startNum = start === "K" ? 1 : parseInt(start);
    const endNum = parseInt(end);

    for (let i = startNum; i <= endNum; i++) {
      gradesArray.push({ value: i.toString(), label: gradeLabel(i) });
    }

    return gradesArray;
  }, [form.school, schoolData]);



  return (
    <div className="home-school-panel-container" style={{ border : DEBUG && '1px solid red' }}>
      
      <div className="home-school-panel-inputs"  style={{ border : DEBUG && '1px solid blue' }}>
        <VirtualizedSelect
          label="State"
          name="state"
          labelText="State"
          value={form.state}
          onChange={handleChange}
          placeholder="Select your state"
          options={states}
          // @ts-ignore
          isLoading={isLoading}
        />
        
        <VirtualizedSelect
          label="School"
          name="school"
          labelText="School"
          value={form.school}
          onChange={handleChange}
          placeholder="Select your School"
          options={schools}
          // @ts-ignore
          isLoading={isLoading}
          isDisabled={!form.state}
        />

        <VirtualizedSelect
          label="Grade"
          name="grade"
          labelText="Grade"
          value={form.grade}
          onChange={handleChange}
          placeholder="Select your Grade"
          options={grades}
           // @ts-ignore
          isLoading={isLoading}
          isDisabled={!form.school}
        />

        <div className="search-panel-inputs-items">
          <label htmlFor="button" className="search-label">Search</label>
          <button onClick={handleSearch} className="home-search-panel-button">
            Search
          </button>
        </div>

        <p className="school-help-text">
          Don't See Your School or Teacher? No problem!{" "}
        <UploadSchoolListDialog 
          className="school-help-link" 
          schoolData={schoolData} 
        />{" "}
          to find out how we can help!
        </p>
      </div>
    </div>                              
  );
}

export default SchoolSearchPanel;


